simulation "vendor-shell" "The depot firewall blocks a vendor shell": {"kind":"constant","ratePerSec":60,"durationMs":16000} from "depot-chargers"; {"kind":"constant","ratePerSec":300,"durationMs":16000} from "street"; {"kind":"constant","ratePerSec":10,"fromMs":3000,"durationMs":8000} from "vendor"; timeline=[{"atMs":0,"action":{"do":"note","text":"Depot chargers reach the cloud through the switch, a firewall pair and the SD-WAN edge. Street chargers come in over LTE.","focus":["depot-chargers","depot-switch","depot-fw","depot-router","street"]}},{"atMs":3000,"action":{"do":"note","text":"The charger vendor tries to open a remote shell into the depot. Its sessions reach the firewall.","focus":["vendor","depot-router","depot-fw"]}},{"atMs":6000,"action":{"do":"note","text":"The firewall's deny rule stops every one. Blocked is the rule working, not a loss; vendor support goes through a ticketed jump host instead.","focus":["depot-fw","depot-switch"]}}]; expectations=[{"id":"blocked","label":"The firewall blocks the vendor shell","metric":{"node":"depot-fw","field":"blocked"},"op":">=","value":50,"when":"end"},{"id":"no-drops","label":"The firewall drops nothing","metric":{"node":"depot-fw","field":"dropped"},"op":"==","value":0,"when":"always"},{"id":"telemetry","label":"Depot telemetry keeps flowing","metric":{"node":"ingress","field":"processed"},"op":">","value":5000,"when":"end"}]
simulation "reboot-storm" "A firmware wave reboots the street fleet": {"kind":"constant","ratePerSec":60,"durationMs":24000} from "depot-chargers"; {"kind":"constant","ratePerSec":300,"durationMs":24000} from "street"; {"kind":"burst","count":12000,"atMs":4000,"spreadMs":3000} from "street"; timeline=[{"atMs":0,"action":{"do":"note","text":"Four consumer groups read charger events: twins, fault detection, metering and capture to the lake.","focus":["events","state","faults","state-db"]}},{"atMs":4000,"action":{"do":"note","text":"The firmware wave lands: 12,000 reconnect messages in three seconds.","focus":["street","ingress","ocpp","events"]}},{"atMs":8000,"action":{"do":"note","text":"Event Hubs holds the burst. The twin updater works through its lag; fault detection and metering keep their own pace.","focus":["events","state","state-db"]}},{"atMs":18000,"action":{"do":"note","text":"Every group has caught up, and nothing was dropped."}}]; expectations=[{"id":"absorbed","label":"The twin updater falls behind for a while","metric":{"node":"events","field":"lag","group":"state"},"op":">","value":1000,"when":"eventually"},{"id":"drained","label":"Every reconnect reaches the twins","metric":{"node":"events","field":"lag","group":"state"},"op":"==","value":0,"when":"end"},{"id":"nothing-lost","label":"Nothing is dropped","metric":{"node":"ocpp","field":"dropped"},"op":"==","value":0,"when":"always"}]
